{"command":"node -e "
const fs = require('fs');
const html = fs.readFileSync('chip8_openrouter-minimax-minimax-m3_01.html', 'utf8');

// Extract script content
const scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
if (!scriptMatch) { console.log('No script found'); process.exit(1); }
const js = scriptMatch[1];
console.log('Script length:', js.length);

// Check syntax
try {
  new Function(js);
  console.log('JavaScript syntax: OK');
} catch(e) {
  console.log('Syntax error:', e.message);
}

// Check for key features
const checks = [
  ['Font at 0x050', /0x050|FONT_START/],
  ['Program at 0x200', /0x200|PROGRAM_START/],
  ['64x32 display', /64.*32|WIDTH.*64|HEIGHT.*32/],
  ['V0-VF registers', /V[0-9A-F]|V\[/],
  ['Index register', /index|I\s*=|register I/],
  ['Stack', /stack/],
  ['Delay timer', /delayTimer|DT/],
  ['Sound timer', /soundTimer|ST/],
  ['CLS instruction', /00E0|0x00E0|cls/],
  ['DRW instruction', /D[0-9A-F]{3}|draw|DRW/],
  ['Key handling', /keydown|keyup/],
  ['Canvas', /canvas|getContext/],
  ['Demo ROM', /DEMO|demoRom|loadDemo/],
  ['File input', /FileReader|file.*input|loadROM/],
  ['Run/Pause/Step/Reset', /run|pause|step|reset/i],
  ['Speed control', /speed|instructionsPerFrame/],
  ['Debugger', /debugger|debug/],
];

checks.forEach(([name, re]) => {
  const found = re.test(html);
  console.log((found ? '✓' : '✗') + ' ' + name);
});

// Check demo ROM bytes
const romMatch = html.match(/DEMO_ROM\s*=\s*\[([\s\S]*?)\]/);
if (romMatch) {
  const bytes = romMatch[1].split(',').map(s => parseInt(s.trim().replace(/0x/g,''), 16)).filter(n => !isNaN(n));
  console.log('Demo ROM bytes:', bytes.length, 'bytes');
  console.log('First 20 bytes:', bytes.slice(0, 20).map(b => '0x' + b.toString(16).padStart(2,'0')).join(' '));
} else {
  console.log('Demo ROM not found in expected format');
}
"
"}

